import{_ as r,C as a,c as s,o as d,aa as l,G as t}from"./chunks/framework.Cn7WEiMX.js";const c="/assets/version-info.Dm7mNfZ_.png",n="data:image/png;base64,",p="/assets/first-step.B36xwNl3.png",u="/assets/dirt-creation.UGfVH9ut.png",g="/assets/grass-creation.BUJDjWOV.png",h="/assets/gravity-fall.IfqsJyi3.png",m="/assets/region-selected.BuQxF_Db.png",f="/assets/landscape-smoothed.CumG0L-L.png",b="/assets/a-tree.W75mozr1.png",k="/assets/some-grass.4f6P7v2R.png",A=JSON.parse('{"title":"使用 WE 制作简单封闭地形","description":"","frontmatter":{"breadcrumbs":[{"title":"Continue Project","link":"/guide"},{"title":"advanced","link":""},{"title":"使用 WE 制作简单封闭地形","link":"/guide/advanced/how-to-make-easy-landscape-using-we"}]},"headers":[],"relativePath":"guide/advanced/how-to-make-easy-landscape-using-we.md","filePath":"guide/advanced/how-to-make-easy-landscape-using-we.md"}'),w={name:"guide/advanced/how-to-make-easy-landscape-using-we.md"};function W(E,e,x,v,S,U){const o=a("NolebaseGitContributors"),i=a("NolebaseGitChangelog");return d(),s("div",null,[e[0]||(e[0]=l('<h1 id="使用-we-制作简单封闭地形" tabindex="-1">使用 WE 制作简单封闭地形 <a class="header-anchor" href="#使用-we-制作简单封闭地形" aria-label="Permalink to &quot;使用 WE 制作简单封闭地形&quot;">​</a></h1><p>维基部分讲过，WorldEdit 是一款功能强大的地图编辑软件，它提供了包括笔刷、造树、地形平滑、范围替换、生成物体等提升制作地图的效率。如果你是一位负责制作地图的管理，那么使用 WE 甚至更高级的 VoxelSniper 或者 Axiom 都是非常有必要的。不过，因为这个章节是为新手准备的，我们只会在下文讲述如何使用 WorldEdit 制作简单的地形。</p><h2 id="准备" tabindex="-1">准备 <a class="header-anchor" href="#准备" aria-label="Permalink to &quot;准备&quot;">​</a></h2><p>你需要准备如下插件或者服务端：</p><ul><li>任意支持 WorldEdit 运行的服务端核心及版本 <ul><li>本教程选择 1.21.4 Purpur，你可以在 <a href="https://api.purpurmc.org/v2/purpur/1.21.4/2416/download" target="_blank" rel="noreferrer">PurpurMC 官网</a>下载到开服核心文件。</li></ul></li><li><a href="https://modrinth.com/plugin/worldedit" target="_blank" rel="noreferrer">WorldEdit</a><ul><li>也可使用 <a href="https://modrinth.com/plugin/fastasyncworldedit" target="_blank" rel="noreferrer">FastAsyncWorldEdit</a>，不过不推荐在高版本使用，因为它有尚未解决的严重编辑漏洞。</li></ul></li><li><a href="https://modrinth.com/mod/worldedit-cui" target="_blank" rel="noreferrer">WorldEdit CUI</a> 模组（可选），<a href="https://www.spigotmc.org/resources/17311/" target="_blank" rel="noreferrer">WorldEditSelectionVisualizer</a>插件，或 <a href="https://www.spigotmc.org/resources/60726/" target="_blank" rel="noreferrer">WorlddEditSUI</a> 插件。它们可以显示你的选择区域，有助于你提高编辑效率。</li></ul><h2 id="教程" tabindex="-1">教程 <a class="header-anchor" href="#教程" aria-label="Permalink to &quot;教程&quot;">​</a></h2><h3 id="_1-首先-安装插件-并启动服务器。如果你已经安装了插件-则可以跳过。" tabindex="-1">1. 首先，安装插件，并启动服务器。如果你已经安装了插件，则可以跳过。 <a class="header-anchor" href="#_1-首先-安装插件-并启动服务器。如果你已经安装了插件-则可以跳过。" aria-label="Permalink to &quot;1. 首先，安装插件，并启动服务器。如果你已经安装了插件，则可以跳过。&quot;">​</a></h3><h3 id="_2-输入命令-worldedit-version-如果你见到了如下消息-则说明插件安装成功。" tabindex="-1">2. 输入命令 <a href="./../../wiki/WorldEdit/commands#通用命令"><code>/worldedit version</code></a>，如果你见到了如下消息，则说明插件安装成功。 <a class="header-anchor" href="#_2-输入命令-worldedit-version-如果你见到了如下消息-则说明插件安装成功。" aria-label="Permalink to &quot;2. 输入命令 [`/worldedit version`](../../wiki/WorldEdit/commands.md#通用命令)，如果你见到了如下消息，则说明插件安装成功。&quot;">​</a></h3><figure><img src="'+c+'" alt="" tabindex="0"><figcaption></figcaption></figure><h3 id="_3-根据你需要的副本类型-创建笔刷。" tabindex="-1">3. 根据你需要的副本类型，创建<a href="./../../wiki/WorldEdit/usage/brushes">笔刷</a>。 <a class="header-anchor" href="#_3-根据你需要的副本类型-创建笔刷。" aria-label="Permalink to &quot;3. 根据你需要的副本类型，创建[笔刷](../../wiki/WorldEdit/usage/brushes.md)。&quot;">​</a></h3><p>创建笔刷的基本命令是 <code>//brush [形状] [方块构成] [半径]</code>。输入命令后，笔刷会被绑定在你手持的物品上。因此，绑定笔刷不能空手进行，否则会返回错误提示。</p><figure><img src="'+n+'" alt="" tabindex="0"><figcaption></figcaption></figure><table tabindex="0"><thead><tr><th>参数名称</th><th>解释</th><th>示例值</th></tr></thead><tbody><tr><td>形状</td><td>笔刷的形状。在本教程中，我们只需要用到球形的笔刷。WorldEdit 自带了许多类型的笔刷，更多内容可以浏览上述的文章。</td><td><code>sphere</code>（球形笔刷）</td></tr><tr><td>方块构成</td><td>笔刷里包含的方块，也就是笔刷“涂抹”后生成的方块。可以用英文逗号 <code>,</code> 表示多个方块。</td><td><code>stone</code>（“涂抹”时放置石头）<br><code>stone,dirt</code>（“涂抹”时放置石头与泥土的混合方块）</td></tr><tr><td>半径</td><td>笔刷的大小。默认配置下最大值为 5。设置得太大可能会导致服务器在你绘制地形的时候产生卡顿。</td><td><code>5</code>（默认配置下允许的最大值）</td></tr></tbody></table><p>根据上述解释，我们先试着拿出一根木棍，再输入命令为其绑定一个<strong>半径为 4，组成为石头（<code>stone</code>）的球形笔刷</strong>吧！</p><details class="details custom-block"><summary>偷看一眼答案？</summary><p>半径为 4，组成为石头（<code>stone</code>），球形笔刷：</p><div class="language-txt vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">txt</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>//brush sphere stone 4</span></span></code></pre></div></details><div class="tip custom-block"><p class="custom-block-title">提示</p><p>你可以通过 TAB 键补全提高输入方块名称的速度！</p></div><h3 id="_4-绑定完成后-你就可以在世界中通过右键点击涂抹笔刷。" tabindex="-1">4. 绑定完成后，你就可以在世界中通过右键点击涂抹笔刷。 <a class="header-anchor" href="#_4-绑定完成后-你就可以在世界中通过右键点击涂抹笔刷。" aria-label="Permalink to &quot;4. 绑定完成后，你就可以在世界中通过右键点击涂抹笔刷。&quot;">​</a></h3><figure><img src="'+p+'" alt="" tabindex="0"><figcaption>看啊，我在一片虚无里涂抹的第一团漂浮的石头！</figcaption></figure><h3 id="_5-按相同的方法为石头上覆盖一层泥土或者草方块。" tabindex="-1">5. 按相同的方法为石头上覆盖一层泥土或者草方块。 <a class="header-anchor" href="#_5-按相同的方法为石头上覆盖一层泥土或者草方块。" aria-label="Permalink to &quot;5. 按相同的方法为石头上覆盖一层泥土或者草方块。&quot;">​</a></h3><div class="tip custom-block"><p class="custom-block-title">提示</p><p>如果你使用的是泥土，你可能需要使用 <code>//green [半径]</code> 把周围的泥土替换成草皮。</p></div><figure><img src="'+u+'" alt="" tabindex="0"><figcaption>覆盖了泥土之后的岩石山地形</figcaption></figure><figure><img src="'+g+'" alt="" tabindex="0"><figcaption>使用了 <code>//green</code> 命令之后的地形</figcaption></figure><h3 id="_6-使用重力笔刷压实地形。" tabindex="-1">6. 使用重力笔刷压实地形。 <a class="header-anchor" href="#_6-使用重力笔刷压实地形。" aria-label="Permalink to &quot;6. 使用重力笔刷压实地形。&quot;">​</a></h3><p>重力笔刷是一类特殊的笔刷，它可以让作用范围内的方块立即坠落到最下层的方块，如果底层是虚空，那么它会落在最底层的位置。这个画笔可以用来排空球形笔刷涂抹过程中产生的空洞。</p><p>重力笔刷的绑定命令是 <code>//brush gravity [半径]</code>。</p><figure><img src="'+h+'" alt="" tabindex="0"><figcaption>压实之后的地面已经初具雏形</figcaption></figure><h3 id="_7-使用小木斧选中你的地形。" tabindex="-1">7. 使用小木斧选中你的地形。 <a class="header-anchor" href="#_7-使用小木斧选中你的地形。" aria-label="Permalink to &quot;7. 使用小木斧选中你的地形。&quot;">​</a></h3><p>你既可以用传统的搭方块设置选区的两个角点，也可以直接选中地面，再用 <code>//expand [距离]</code> 将选区朝你看着的方向拓宽。</p><div class="tip custom-block"><p class="custom-block-title">选太多了怎么办？</p><p>你可以用 <code>//contract [距离]</code> 命令，用相同的方式收缩选区。</p></div><figure><img src="'+m+'" alt="" tabindex="0"><figcaption>选中的地形</figcaption></figure><p>这里的红色框是 WorldEdit CUI 带来的效果。<br> 如果你安装的是上述的两个插件，那么这里有可能是火焰粒子。</p><h3 id="_8-使用地形平滑命令。" tabindex="-1">8. 使用地形平滑命令。 <a class="header-anchor" href="#_8-使用地形平滑命令。" aria-label="Permalink to &quot;8. 使用地形平滑命令。&quot;">​</a></h3><p>地形平滑（<code>//smooth [重复次数]</code>）是本次教程中非常重要的一个指令。它可以让你的地形趋于平滑，更加自然。虽然没有像专业的地形编辑用户那样有酷炫的地形，但是造出一片简单美观的山丘已经非常足够了。</p><p>直接输入 <code>//smooth</code> 表示执行一次地形平滑。输入 <code>//smooth 10</code> 表示对区域内同时施加十次连续的地形平滑。</p><figure><img src="'+f+'" alt="" tabindex="0"><figcaption>平滑过后的地形</figcaption></figure><p>大功告成！现在，你有了一块相对圆滑的地形。封闭式的地形也可以用相同的方法制作。</p><h3 id="_9-进阶-利用树木笔刷与植被命令布置简单的装饰" tabindex="-1">9.（进阶）利用树木笔刷与植被命令布置简单的装饰 <a class="header-anchor" href="#_9-进阶-利用树木笔刷与植被命令布置简单的装饰" aria-label="Permalink to &quot;9.（进阶）利用树木笔刷与植被命令布置简单的装饰&quot;">​</a></h3><p>顾名思义，树木笔刷就是在玩家点击的位置生成一棵树。</p><p>命令的用法是 <code>/tree [树种]</code>，在这个例子中，我们以橡树（<code>oak</code>）为例。<br> 站在你需要的位置，输入 <code>/tree oak</code>，笔刷就会绑定在你当前的物品上。<br> 这时点击地面，一棵树就会生成在这里。</p><div class="tip custom-block"><p class="custom-block-title">卡在树里怎么办？</p><p>试试看输入命令 <code>/unstuck</code>，它可以把你从方块中解救出来！</p></div><figure><img src="'+b+'" alt="" tabindex="0"><figcaption>一棵通过 <code>/tree</code> 命令生成的树木。</figcaption></figure><p>再次圈定选区，输入命令 <code>//flora [密度]</code>，插件就会为你在区域里生成植被。</p><figure><img src="'+k+'" alt="" tabindex="0"><figcaption>分布在漂浮岛屿上的稀疏植被。</figcaption></figure><p>这个命令与直接使用骨粉的效果差别不大，它还会为你贴心地往草堆里插花。如果你想要让植被更茂盛一些，试试输入命令 <code>//flora 80</code>，这可以让植被密度达到 80%。<br> 除此之外，命令在区域内生成的植被类型还和生物群系有关系，如果你知道如何通过命令修改选区的生物群系，你就可以让这个命令在区域里生成丛林的蕨类植物。</p><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><ul><li>通过命令绑定笔刷，修正地形</li><li>在选区内通过命令平滑地形</li><li>通过命令与笔刷添加植被，进一步美化地形</li></ul>',46)),t(o),t(i)])}const q=r(w,[["render",W]]);export{A as __pageData,q as default};
